    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: We want to minimize the post_residual (Best Fit).
    // Penalize large empty spaces, but normalize by capacity.
    let mut score = post_res;

    // Penalty for creating a bin that is too small for the lookahead item.
    // If we have a next_item_size, we favor bins that can accommodate it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_res).powf(1.5);
    }

    // Dynamic pressure: As the stream progresses, increase the cost of opening new bins.
    // This forces the algorithm to be more aggressive with packing as total_items approaches.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 + progress * 2.0);
    }

    // Interaction with existing bins:
    // If this bin is the only one that fits the current item, prioritize it heavily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Smooth non-linear coupling:
    // If the post_residual is small (e.g., < 10), it's a "tight" fit.
    // We reward tight fits exponentially to discourage fragmentation.
    if post_res < 10.0 {
        score -= (10.0 - post_res).powf(1.2);
    }

    // Mean residual balance:
    // Avoid creating bins that significantly deviate from the mean usage of existing bins.
    let dev = (post_res - mean_residual).abs();
    score += dev * 0.1;

    score
}

