pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Decreasing logic: We want to minimize the post_residual (Best Fit).
    // The base score is already post_residual.

    // 2. Penalty for creating "dead space":
    // If the post_residual is small (e.g., 1-9), it is often unusable. 
    // We penalize these "slivers" to encourage leaving larger gaps for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // 3. Lookahead integration:
    // If the next item is large, we should prioritize keeping the current residual 
    // large enough to accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that cannot fit the next item if we have other options.
            score += 15.0;
        } else {
            // Reward bins that can fit the next item.
            score -= 5.0;
        }
    }

    // 4. Global state pressure:
    // If we have many open bins, we want to consolidate (Best Fit).
    // If we have few open bins, we can afford to be more selective.
    if open_bins_count > 5 {
        // Aggressive consolidation
        score += (open_bins_count as f64) * 0.5;
    }

    // 5. Handling the "New Bin" candidate:
    // If bin_residual == bin_capacity, this is a new bin. 
    // We only want to open a new bin if the existing bins produce poor fits (large residuals).
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is high,
        // or if we are forced to (fitting_bins_count == 0).
        if fitting_bins_count == 0 {
            score = -10.0; // Force opening a new bin if no other option exists
        } else {
            // Otherwise, make opening a new bin expensive to favor packing into existing space.
            score = 40.0 + (mean_residual * 0.5);
        }
    }

    // 6. Final adjustment: 
    // Favor bins that are already "tight" to keep the number of bins low.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement. 
    // We want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating a "fragmented" bin (a small residual that is hard to fill).
    // Small residuals (e.g., 1-9) are highly undesirable.
    if post > 0.0 && post < 10.0 {
        score += 50.0 / (post + 1.0);
    }

    // Lookahead logic: If the next item doesn't fit in this post-residual, 
    // penalize the bin proportional to the expected utility of the remaining space.
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 15.0 * (next_item_size as f64 / (post + 1.0));
    }

    // Dynamic adaptation: As the stream progresses, prioritize tighter packing 
    // to avoid leaving too many bins partially full at the end.
    // We increase the cost of leaving larger residuals as progress increases.
    score += (post * progress * 0.5);

    // If this is the last chance for the current item (fitting_bins_count == 1),
    // strongly favor this bin over opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // If considering a new bin (bin_residual == bin_capacity), apply a high base cost
    // to ensure we only open a new bin if the existing options are truly terrible.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // Coupling with mean_residual: Favor bins that stay close to the current average 
    // to maintain a uniform distribution of fill levels.
    score += (post - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead zones': residual space too small for any likely future item (under 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic preference: favor post_residuals that are multiples of 20 (e.g., 20, 40, 60)
    // as they provide high flexibility for the 10-80 item range.
    let harmonic_penalty = (post_residual % 20) as f64;
    score += harmonic_penalty * 1.5;

    // Lookahead logic: if next_item_size is large, prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0;
        } else {
            // Reward bins that leave exactly enough space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // If this is the only bin that fits the current item, prioritize it to avoid new bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // New bin bias: discourage opening a new bin unless existing bins are highly fragmented.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
        if mean_residual > 40.0 {
            score -= 20.0;
        }
    }

    // Progression: As the stream nears completion, become more aggressive in packing tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}
